package com.itu.gestionRH.controller.organization;
import com.itu.gestionRH.entity.organization.*;import com.itu.gestionRH.repository.organization.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api/v1/conges/soldes") public class CongeSoldeController{final CongeSoldeRepository soldes;final EmployeRepository employes;public CongeSoldeController(CongeSoldeRepository s,EmployeRepository e){soldes=s;employes=e;}public record Request(Long employeId,Integer annee,double joursAcquis){}@GetMapping @PreAuthorize("hasAnyAuthority('PERM_DEMANDE_CREER','PERM_CONTRAT_GERER')")public java.util.List<CongeSolde> all(){return soldes.findAll();}@PostMapping @Transactional @PreAuthorize("hasAnyAuthority('PERM_DEMANDE_CREER','PERM_CONTRAT_GERER')")public CongeSolde save(@RequestBody Request r){CongeSolde s=soldes.findByEmployeIdAndAnnee(r.employeId(),r.annee()).orElseGet(CongeSolde::new);s.setEmploye(employes.findById(r.employeId()).orElseThrow());s.setAnnee(r.annee());s.setJoursAcquis(r.joursAcquis());double report=soldes.findByEmployeIdAndAnnee(r.employeId(),r.annee()-1).map(x->Math.max(0,x.getDisponible())).orElse(0d);s.setJoursReportes(report);return soldes.save(s);}}
